\"flow\": \"implicit\",\n      \"scopes\": {\n        \"accounts\": \"This scope will group the AccountAPI related operations.\"\n      },\n      \"x-scopes-bindings\": {\n        \"accounts\": \"Internal/consumer\"\n      }\n    }\n  },\n  \"definitions\": {\n    \"OBReadConsent1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\",\n        \"Risk\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"$ref\": \"#/definitions/OBReadData1\"\n        },\n        \"Risk\": {\n          \"$ref\": \"#/definitions/OBRisk2\"\n        }\n      }\n    },\n    \"OBReadConsentResponse1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\",\n        \"Risk\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"ConsentId\": {\n              \"type\": \"string\",\n              \"description\": \"Unique identification as assigned to identify the account access consent resource.\",\n              \"minLength\": 1,\n              \"maxLength\": 128\n            },\n            \"CreationDateTime\": {\n              \"$ref\": \"#/definitions/CreationDateTime\"\n            },\n            \"Status\": {\n              \"$ref\": \"#/definitions/OBExternalRequestStatus1Code\"\n            },\n            \"StatusUpdateDateTime\": {\n              \"$ref\": \"#/definitions/StatusUpdateDateTime\"\n            },\n            \"Permissions\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/definitions/OBExternalPermissions1Code\"\n              },\n              \"minItems\": 1\n            },\n            \"ExpirationDateTime\": {\n              \"type\": \"string\",\n              \"format\": \"date-time\",\n              \"description\": \"Specified date and time the permissions will expire.\\nIf this is not populated, the permissions will be open ended.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n            },\n            \"TransactionFromDateTime\": {\n              \"type\": \"string\",\n              \"format\": \"date-time\",\n              \"description\": \"Specified start date and time for the transaction query period.\\nIf this is not populated, the start date will be open ended, and data will be returned from the earliest available transaction.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n            },\n            \"TransactionToDateTime\": {\n              \"type\": \"string\",\n              \"format\": \"date-time\",\n              \"description\": \"Specified end date and time for the transaction query period.\\nIf this is not populated, the end date will be open ended, and data will be returned to the latest available transaction.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n            }\n          },\n          \"required\": [\n            \"ConsentId\",\n            \"CreationDateTime\",\n            \"Permissions\",\n            \"StatusUpdateDateTime\"\n          ]\n        },\n        \"Risk\": {\n          \"$ref\": \"#/definitions/OBRisk2\"\n        },\n        \"Links\": {\n          \"$ref\": \"#/definitions/Links\"\n        },\n        \"Meta\": {\n          \"$ref\": \"#/definitions/Meta\"\n        }\n      }\n    },\n    \"OBReadData1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Permissions\"\n      ],\n      \"properties\": {\n        \"Permissions\": {\n          \"type\": \"array\",\n          \"description\": \"Specifies the Open Banking account access data types. This is a list of the data clusters being consented by the PSU, and requested for authorisation with the ASPSP.\",\n          \"items\": {\n            \"$ref\": \"#/definitions/OBExternalPermissions1Code\"\n          },\n          \"minItems\": 1\n        },\n        \"ExpirationDateTime\": {\n          \"type\": \"string\",\n          \"format\": \"date-time\",\n          \"description\": \"Specified date and time the permissions will expire.\\nIf this is not populated, the permissions will be open ended.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n        },\n        \"TransactionFromDateTime\": {\n          \"type\": \"string\",\n          \"format\": \"date-time\",\n          \"description\": \"Specified start date and time for the transaction query period.\\nIf this is not populated, the start date will be open ended, and data will be returned from the earliest available transaction.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n        },\n        \"TransactionToDateTime\": {\n          \"type\": \"string\",\n          \"format\": \"date-time\",\n          \"description\": \"Specified end date and time for the transaction query period.\\nIf this is not populated, the end date will be open ended, and data will be returned to the latest available transaction.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n        }\n      }\n    },\n    \"OBRisk2\": {\n      \"type\": \"object\",\n      \"description\": \"The Risk section is sent by the initiating party to the ASPSP. It is used to specify additional details for risk scoring for Account Info.\",\n      \"additionalProperties\": {}\n    },\n    \"OBExternalPermissions1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Specifies the Open Banking account access data types. This is a\\n    list of the data clusters being consented by the PSU, and\\n    requested for authorisation with the ASPSP.\",\n      \"enum\": [\n        \"ReadAccountsBasic\",\n        \"ReadAccountsDetail\",\n        \"ReadBalances\",\n        \"ReadTransactionsDetail\"\n      ]\n    },\n    \"CreationDateTime\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Date and time at which the resource was created.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n    },\n    \"StatusUpdateDateTime\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Date and time at which the resource status was updated.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n    },\n    \"OBExternalRequestStatus1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Specifies the status of consent resource in code form.\",\n      \"enum\": [\n        \"Authorised\",\n        \"AwaitingAuthorisation\",\n        \"Rejected\",\n        \"Revoked\"\n      ]\n    },\n    \"OBReadAccount4\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"Account\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/definitions/OBAccount4\"\n              }\n            }\n          }\n        },\n        \"Links\": {\n          \"$ref\": \"#/definitions/Links\"\n        },\n        \"Meta\": {\n          \"$ref\": \"#/definitions/Meta\"\n        }\n      }\n    },\n    \"OBReadAccount5\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"Account\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/definitions/OBAccount4\"\n              }\n            }\n          }\n        },\n        \"Links\": {\n          \"$ref\": \"#/definitions/Links\"\n        },\n        \"Meta\": {\n          \"$ref\": \"#/definitions/Meta\"\n        }\n      },\n      \"additionalProperties\": {}\n    },\n    \"OBAccount4\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"AccountId\",\n        \"AccountSubType\",\n        \"AccountType\",\n        \"Currency\"\n      ],\n      \"properties\": {\n        \"AccountId\": {\n          \"$ref\": \"#/definitions/AccountId\"\n        },\n        \"Status\": {\n          \"$ref\": \"#/definitions/OBAccountStatus1Code\"\n        },\n        \"StatusUpdateDateTime\": {\n          \"$ref\": \"#/definitions/StatusUpdateDateTime\"\n        },\n        \"Currency\": {\n          \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n        },\n        \"AccountType\": {\n          \"$ref\": \"#/definitions/OBExternalAccountType1Code\"\n        },\n        \"AccountSubType\": {\n          \"$ref\": \"#/definitions/OBExternalAccountSubType1Code\"\n        },\n        \"Description\": {\n          \"$ref\": \"#/definitions/Description\"\n        },\n        \"Nickname\": {\n          \"$ref\": \"#/definitions/Nickname\"\n        },\n        \"Account\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"object\",\n            \"description\": \"Provides the details to identify an account.\",\n            \"properties\": {\n              \"SchemeName\": {\n                \"$ref\": \"#/definitions/OBExternalAccountIdentification4Code\"\n              },\n              \"Identification\": {\n                \"$ref\": \"#/definitions/Identification\"\n              },\n              \"Name\": {\n                \"$ref\": \"#/definitions/Name\"\n              },\n              \"SecondaryIdentification\": {\n                \"$ref\": \"#/definitions/SecondaryIdentification\"\n              }\n            },\n            \"required\": [\n              \"Identification\",\n              \"SchemeName\"\n            ]\n          }\n        },\n        \"Servicer\": {\n          \"$ref\": \"#/definitions/OBBranchAndFinancialInstitutionIdentification5\"\n        }\n      },\n      \"description\": \"Unambiguous identification of the account to which credit and debit entries are made.\"\n    },\n    \"OBReadBalance1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"Balance\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"type\": \"object\",\n                \"description\": \"Set of elements used to define the balance details.\",\n                \"properties\": {\n                  \"AccountId\": {\n                    \"$ref\": \"#/definitions/AccountId\"\n                  },\n                  \"CreditDebitIndicator\": {\n                    \"$ref\": \"#/definitions/OBCreditDebitCode\"\n                  },\n                  \"Type\": {\n                    \"$ref\": \"#/definitions/OBBalanceType1Code\"\n                  },\n                  \"DateTime\": {\n                    \"type\": \"string\",\n                    \"format\": \"date-time\",\n                    \"description\": \"Indicates the date (and time) of the balance.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n                  },\n                  \"Amount\": {\n                    \"type\": \"object\",\n                    \"description\": \"Amount of money of the cash balance.\",\n                    \"properties\": {\n                      \"Amount\": {\n                        \"$ref\": \"#/definitions/OBActiveCurrencyAndAmount_SimpleType\"\n                      },\n                      \"Currency\": {\n                        \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n                      }\n                    },\n                    \"required\": [\n                      \"Amount\",\n                      \"Currency\"\n                    ]\n                  },\n                  \"CreditLine\": {\n                    \"type\": \"array\",\n                    \"items\": {\n                      \"type\": \"object\",\n                      \"description\": \"Set of elements used to provide details on the credit line.\",\n                      \"properties\": {\n                        \"Included\": {\n                          \"type\": \"boolean\",\n                          \"description\": \"Indicates whether or not the credit line is included in the balance of the account.\\nUsage: If not present, credit line is not included in the balance amount of the account.\"\n                        },\n                        \"Type\": {\n                          \"type\": \"string\",\n                          \"description\": \"Limit type, in a coded form.\",\n                          \"enum\": [\n                            \"Available\",\n                            \"Credit\",\n                            \"Emergency\",\n                            \"Pre-Agreed\",\n                            \"Temporary\"\n                          ]\n                        },\n                        \"Amount\": {\n                          \"type\": \"object\",\n                          \"description\": \"Amount of money of the credit line.\",\n                          \"properties\": {\n                            \"Amount\": {\n                              \"$ref\": \"#/definitions/OBActiveCurrencyAndAmount_SimpleType\"\n                            },\n                            \"Currency\": {\n                              \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n                            }\n                          },\n                          \"required\": [\n                            \"Amount\",\n                            \"Currency\"\n                          ]\n                        }\n                      },\n                      \"required\": [\n                        \"Included\"\n                      ]\n                    }\n                  }\n                },\n                \"required\": [\n                  \"AccountId\",\n                  \"Amount\",\n                  \"CreditDebitIndicator\",\n                  \"DateTime\",\n                  \"Type\"\n                ]\n              },\n              \"minItems\": 1\n            }\n          },\n          \"required\": [\n            \"Balance\"\n          ]\n        },\n        \"Links\": {\n          \"$ref\": \"#/definitions/Links\"\n        },\n        \"Meta\": {\n          \"$ref\": \"#/definitions/Meta\"\n        }\n      }\n    },\n    \"OBReadTransaction5\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Data\"\n      ],\n      \"properties\": {\n        \"Data\": {\n          \"$ref\": \"#/definitions/OBReadDataTransaction5\"\n        },\n        \"Links\": {\n          \"$ref\": \"#/definitions/Links\"\n        },\n        \"Meta\": {\n          \"$ref\": \"#/definitions/Meta\"\n        }\n      }\n    },\n    \"OBReadDataTransaction5\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"Transaction\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/definitions/OBTransaction5\"\n          }\n        }\n      }\n    },\n    \"OBTransaction5\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"AccountId\",\n        \"Amount\",\n        \"BookingDateTime\",\n        \"CreditDebitIndicator\",\n        \"Status\"\n      ],\n      \"properties\": {\n        \"AccountId\": {\n          \"$ref\": \"#/definitions/AccountId\"\n        },\n        \"TransactionId\": {\n          \"$ref\": \"#/definitions/TransactionId\"\n        },\n        \"TransactionReference\": {\n          \"$ref\": \"#/definitions/TransactionReference\"\n        },\n        \"StatementReference\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/definitions/StatementReference\"\n          }\n        },\n        \"CreditDebitIndicator\": {\n          \"$ref\": \"#/definitions/OBCreditDebitCode\"\n        },\n        \"Status\": {\n          \"$ref\": \"#/definitions/OBEntryStatus1Code\"\n        },\n        \"BookingDateTime\": {\n          \"$ref\": \"#/definitions/BookingDateTime\"\n        },\n        \"ValueDateTime\": {\n          \"$ref\": \"#/definitions/ValueDateTime\"\n        },\n        \"TransactionInformation\": {\n          \"$ref\": \"#/definitions/TransactionInformation\"\n        },\n        \"AddressLine\": {\n          \"$ref\": \"#/definitions/AddressLine\"\n        },\n        \"Amount\": {\n          \"$ref\": \"#/definitions/OBActiveOrHistoricCurrencyAndAmount\"\n        },\n        \"ChargeAmount\": {\n          \"$ref\": \"#/definitions/OBActiveOrHistoricCurrencyAndAmount\"\n        },\n        \"CurrencyExchange\": {\n          \"$ref\": \"#/definitions/OBCurrencyExchange5\"\n        },\n        \"BankTransactionCode\": {\n          \"$ref\": \"#/definitions/OBBankTransactionCodeStructure1\"\n        },\n        \"ProprietaryBankTransactionCode\": {\n          \"$ref\": \"#/definitions/ProprietaryBankTransactionCodeStructure1\"\n        },\n        \"Balance\": {\n          \"$ref\": \"#/definitions/OBTransactionCashBalance\"\n        },\n        \"MerchantDetails\": {\n          \"$ref\": \"#/definitions/OBMerchantDetails1\"\n        },\n        \"CreditorAgent\": {\n          \"$ref\": \"#/definitions/OBBranchAndFinancialInstitutionIdentification6\"\n        },\n        \"CreditorAccount\": {\n          \"$ref\": \"#/definitions/OBCashAccount6\"\n        },\n        \"DebtorAgent\": {\n          \"$ref\": \"#/definitions/OBBranchAndFinancialInstitutionIdentification6\"\n        },\n        \"DebtorAccount\": {\n          \"$ref\": \"#/definitions/OBCashAccount6\"\n        },\n        \"CardInstrument\": {\n          \"$ref\": \"#/definitions/OBTransactionCardInstrument1\"\n        },\n        \"SupplementaryData\": {\n          \"$ref\": \"#/definitions/OBSupplementaryData1\"\n        }\n      },\n      \"description\": \"Provides further details on an entry in the report.\"\n    },\n    \"AccountId\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 40,\n      \"description\": \"A unique and immutable identifier used to identify the account resource. This identifier has no meaning to the account owner.\"\n    },\n    \"OBAccountStatus1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Specifies the status of account resource in code form.\",\n      \"enum\": [\n        \"Deleted\",\n        \"Disabled\",\n        \"Enabled\",\n        \"Pending\",\n        \"ProForma\"\n      ]\n    },\n    \"ActiveOrHistoricCurrencyCode\": {\n      \"type\": \"string\",\n      \"pattern\": \"^[A-Z]{3,3}$\",\n      \"description\": \"Identification of the currency in which the account is held.\\nUsage: Currency should only be used in case one and the same account number covers several currencies\\nand the initiating party needs to identify which currency needs to be used for settlement on the account.\"\n    },\n    \"OBExternalAccountType1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Specifies the type of account (personal or business).\",\n      \"enum\": [\n        \"Business\",\n        \"Personal\"\n      ]\n    },\n    \"OBExternalAccountSubType1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Specifies the sub type of account (product family group).\",\n      \"enum\": [\n        \"ChargeCard\",\n        \"CreditCard\",\n        \"CurrentAccount\",\n        \"EMoney\",\n        \"Loan\",\n        \"Mortgage\",\n        \"PrePaidCard\",\n        \"Savings\"\n      ]\n    },\n    \"Description\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 35,\n      \"description\": \"Specifies the description of the account type.\"\n    },\n    \"Nickname\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 70,\n      \"description\": \"The nickname of the account, assigned by the account owner in order to provide an additional means of identification of the account.\"\n    },\n    \"OBExternalAccountIdentification4Code\": {\n      \"type\": \"string\",\n      \"description\": \"Name of the identification scheme, in a coded form as published in an external list.\",\n      \"x-namespaced-enum\": [\n        \"UK.OBIE.BBAN\",\n        \"UK.OBIE.IBAN\",\n        \"UK.OBIE.PAN\",\n        \"UK.OBIE.Paym\",\n        \"UK.OBIE.SortCodeAccountNumber\"\n      ]\n    },\n    \"Identification\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 256,\n      \"description\": \"Identification assigned by an institution to identify an account. This identification is known by the account owner.\"\n    },\n    \"Name\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 70,\n      \"description\": \"The account name is the name or names of the account owner(s) represented at an account level, as displayed by the ASPSP\\u0027s online channels.\\nNote, the account name is not the product name or the nickname of the account.\"\n    },\n    \"SecondaryIdentification\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 34,\n      \"description\": \"This is secondary identification of the account, as assigned by the account servicing institution.\\nThis can be used by building societies to additionally identify accounts with a roll number (in addition to a sort code and account number combination).\"\n    },\n    \"OBBranchAndFinancialInstitutionIdentification5\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Identification\",\n        \"SchemeName\"\n      ],\n      \"properties\": {\n        \"SchemeName\": {\n          \"$ref\": \"#/definitions/OBExternalFinancialInstitutionIdentification4Code\"\n        },\n        \"Identification\": {\n          \"$ref\": \"#/definitions/Identification\"\n        }\n      },\n      \"description\": \"Party that manages the account on behalf of the account owner, that is manages the registration and booking of entries on the account, calculates balances on the account and provides information about the account.\"\n    },\n    \"OBExternalFinancialInstitutionIdentification4Code\": {\n      \"type\": \"string\",\n      \"description\": \"Name of the identification scheme, in a coded form as published in an external list.\",\n      \"x-namespaced-enum\": [\n        \"UK.OBIE.BICFI\"\n      ]\n    },\n    \"OBCreditDebitCode\": {\n      \"type\": \"string\",\n      \"description\": \"Indicates whether the balance is a credit or a debit balance.\\nUsage: A zero balance is considered to be a credit balance.\",\n      \"enum\": [\n        \"Credit\",\n        \"Debit\"\n      ]\n    },\n    \"OBBalanceType1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Balance type, in a coded form.\",\n      \"enum\": [\n        \"ClosingAvailable\",\n        \"ClosingBooked\",\n        \"ClosingCleared\",\n        \"Expected\",\n        \"ForwardAvailable\",\n        \"Information\",\n        \"InterimAvailable\",\n        \"InterimBooked\",\n        \"InterimCleared\",\n        \"OpeningAvailable\",\n        \"OpeningBooked\",\n        \"OpeningCleared\",\n        \"PreviouslyClosedBooked\"\n      ]\n    },\n    \"OBActiveCurrencyAndAmount_SimpleType\": {\n      \"type\": \"string\",\n      \"pattern\": \"^\\\\d{1,13}\\\\.\\\\d{1,5}$\",\n      \"description\": \"A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.\"\n    },\n    \"TransactionId\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 210,\n      \"description\": \"Unique identifier for the transaction within an servicing institution. This identifier is both unique and immutable.\"\n    },\n    \"TransactionInformation\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 500,\n      \"description\": \"Further details of the transaction.\\nThis is the transaction narrative, which is unstructured text.\"\n    },\n    \"TransactionReference\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 35,\n      \"description\": \"Unique reference for the transaction. This reference is optionally populated, and may as an example be the FPID in the Faster Payments context.\"\n    },\n    \"StatementReference\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 35,\n      \"description\": \"Unique reference for the statement. This reference may be optionally populated if available.\"\n    },\n    \"OBEntryStatus1Code\": {\n      \"type\": \"string\",\n      \"description\": \"Status of a transaction entry on the books of the account servicer.\",\n      \"enum\": [\n        \"Booked\",\n        \"Pending\"\n      ]\n    },\n    \"BookingDateTime\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Date and time when a transaction entry is posted to an account on the account servicer\\u0027s books.\\nUsage: Booking date is the expected booking date, unless the status is booked, in which case it is the actual booking date.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n    },\n    \"ValueDateTime\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"Date and time at which assets become available to the account owner in case of a credit entry, or cease to be available to the account owner in case of a debit transaction entry.\\nUsage: If transaction entry status is pending and value date is present, then the value date refers to an expected/requested value date.\\nFor transaction entries subject to availability/float and for which availability information is provided, the value date must not be used. In this case the availability component identifies the number of availability days.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n    },\n    \"AddressLine\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"maxLength\": 70,\n      \"description\": \"Information that locates and identifies a specific address for a transaction entry, that is presented in free format text.\"\n    },\n    \"OBActiveOrHistoricCurrencyAndAmount\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Amount\",\n        \"Currency\"\n      ],\n      \"properties\": {\n        \"Amount\": {\n          \"$ref\": \"#/definitions/OBActiveCurrencyAndAmount_SimpleType\"\n        },\n        \"Currency\": {\n          \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n        }\n      },\n      \"description\": \"Amount of money in the cash transaction entry.\"\n    },\n    \"OBCurrencyExchange5\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"ExchangeRate\",\n        \"SourceCurrency\"\n      ],\n      \"properties\": {\n        \"SourceCurrency\": {\n          \"type\": \"string\",\n          \"description\": \"Currency from which an amount is to be converted in a currency conversion.\",\n          \"pattern\": \"^[A-Z]{3,3}$\"\n        },\n        \"TargetCurrency\": {\n          \"type\": \"string\",\n          \"description\": \"Currency into which an amount is to be converted in a currency conversion.\",\n          \"pattern\": \"^[A-Z]{3,3}$\"\n        },\n        \"UnitCurrency\": {\n          \"type\": \"string\",\n          \"description\": \"Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP \\u003d xxxCUR, the unit currency is GBP.\",\n          \"pattern\": \"^[A-Z]{3,3}$\"\n        },\n        \"ExchangeRate\": {\n          \"type\": \"number\",\n          \"description\": \"Factor used to convert an amount from one currency into another. This reflects the price at which one currency was bought with another currency.\\nUsage: ExchangeRate expresses the ratio between UnitCurrency and QuotedCurrency (ExchangeRate \\u003d UnitCurrency/QuotedCurrency).\"\n        },\n        \"ContractIdentification\": {\n          \"type\": \"string\",\n          \"description\": \"Unique identification to unambiguously identify the foreign exchange contract.\",\n          \"minLength\": 1,\n          \"maxLength\": 35\n        },\n        \"QuotationDate\": {\n          \"type\": \"string\",\n          \"format\": \"date-time\",\n          \"description\": \"Date and time at which an exchange rate is quoted.All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n        },\n        \"InstructedAmount\": {\n          \"type\": \"object\",\n          \"description\": \"Amount of money to be moved between the debtor and creditor, before deduction of charges, expressed in the currency as ordered by the initiating party.\",\n          \"properties\": {\n            \"Amount\": {\n              \"$ref\": \"#/definitions/OBActiveCurrencyAndAmount_SimpleType\"\n            },\n            \"Currency\": {\n              \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n            }\n          },\n          \"required\": [\n            \"Amount\",\n            \"Currency\"\n          ]\n        }\n      },\n      \"description\": \"Set of elements used to provide details on the currency exchange.\"\n    },\n    \"OBBankTransactionCodeStructure1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Code\",\n        \"SubCode\"\n      ],\n      \"properties\": {\n        \"Code\": {\n          \"type\": \"string\",\n          \"description\": \"Specifies the family within a domain.\"\n        },\n        \"SubCode\": {\n          \"type\": \"string\",\n          \"description\": \"Specifies the sub-product family within a specific family.\"\n        }\n      },\n      \"description\": \"Set of elements used to fully identify the type of underlying transaction resulting in an entry.\"\n    },\n    \"ProprietaryBankTransactionCodeStructure1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Code\"\n      ],\n      \"properties\": {\n        \"Code\": {\n          \"type\": \"string\",\n          \"description\": \"Proprietary bank transaction code to identify the underlying transaction.\",\n          \"minLength\": 1,\n          \"maxLength\": 35\n        },\n        \"Issuer\": {\n          \"type\": \"string\",\n          \"description\": \"Identification of the issuer of the proprietary bank transaction code.\",\n          \"minLength\": 1,\n          \"maxLength\": 35\n        }\n      },\n      \"description\": \"Set of elements to fully identify a proprietary bank transaction code.\"\n    },\n    \"OBMerchantDetails1\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"MerchantName\": {\n          \"type\": \"string\",\n          \"description\": \"Name by which the merchant is known.\",\n          \"minLength\": 1,\n          \"maxLength\": 350\n        },\n        \"MerchantCategoryCode\": {\n          \"type\": \"string\",\n          \"description\": \"Category code conform to ISO 18245, related to the type of services or goods the merchant provides for the transaction.\",\n          \"minLength\": 3,\n          \"maxLength\": 4\n        }\n      },\n      \"description\": \"Details of the merchant involved in the transaction.\"\n    },\n    \"OBTransactionCashBalance\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Amount\",\n        \"CreditDebitIndicator\",\n        \"Type\"\n      ],\n      \"properties\": {\n        \"CreditDebitIndicator\": {\n          \"$ref\": \"#/definitions/OBCreditDebitCode\"\n        },\n        \"Type\": {\n          \"$ref\": \"#/definitions/OBBalanceType1Code\"\n        },\n        \"Amount\": {\n          \"type\": \"object\",\n          \"description\": \"Amount of money of the cash balance after a transaction entry is applied to the account..\",\n          \"properties\": {\n            \"Amount\": {\n              \"$ref\": \"#/definitions/OBActiveCurrencyAndAmount_SimpleType\"\n            },\n            \"Currency\": {\n              \"$ref\": \"#/definitions/ActiveOrHistoricCurrencyCode\"\n            }\n          },\n          \"required\": [\n            \"Amount\",\n            \"Currency\"\n          ]\n        }\n      },\n      \"description\": \"Set of elements used to define the balance as a numerical representation of the net increases and decreases in an account after a transaction entry is applied to the account.\"\n    },\n    \"OBBranchAndFinancialInstitutionIdentification6\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"SchemeName\": {\n          \"$ref\": \"#/definitions/OBExternalFinancialInstitutionIdentification4Code\"\n        },\n        \"Identification\": {\n          \"$ref\": \"#/definitions/Identification\"\n        },\n        \"Name\": {\n          \"$ref\": \"#/definitions/Name\"\n        },\n        \"PostalAddress\": {\n          \"type\": \"object\",\n          \"properties\": {}\n        }\n      },\n      \"description\": \"Financial institution servicing an account for the creditor.\"\n    },\n    \"OBCashAccount6\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"SchemeName\": {\n          \"$ref\": \"#/definitions/OBExternalAccountIdentification4Code\"\n        },\n        \"Identification\": {\n          \"$ref\": \"#/definitions/Identification\"\n        },\n        \"Name\": {\n          \"$ref\": \"#/definitions/Name\"\n        },\n        \"SecondaryIdentification\": {\n          \"$ref\": \"#/definitions/SecondaryIdentification\"\n        }\n      },\n      \"description\": \"Unambiguous identification of the account of the creditor, in the case of a debit transaction.\"\n    },\n    \"OBTransactionCardInstrument1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"CardSchemeName\"\n      ],\n      \"properties\": {\n        \"CardSchemeName\": {\n          \"type\": \"string\",\n          \"description\": \"Name of the card scheme.\",\n          \"enum\": [\n            \"AmericanExpress\",\n            \"Diners\",\n            \"Discover\",\n            \"MasterCard\",\n            \"VISA\"\n          ]\n        },\n        \"AuthorisationType\": {\n          \"type\": \"string\",\n          \"description\": \"The card authorisation type.\",\n          \"enum\": [\n            \"ConsumerDevice\",\n            \"Contactless\",\n            \"None\",\n            \"PIN\"\n          ]\n        },\n        \"Name\": {\n          \"type\": \"string\",\n          \"description\": \"Name of the cardholder using the card instrument.\",\n          \"minLength\": 1,\n          \"maxLength\": 70\n        },\n        \"Identification\": {\n          \"type\": \"string\",\n          \"description\": \"Identification assigned by an institution to identify the card instrument used in the transaction. This identification is known by the account owner, and may be masked.\",\n          \"minLength\": 1,\n          \"maxLength\": 34\n        }\n      },\n      \"description\": \"Set of elements to describe the card instrument used in the transaction.\"\n    },\n    \"OBSupplementaryData1\": {\n      \"type\": \"object\",\n      \"description\": \"Additional information that can not be captured in the structured fields and/or any other specific block.\",\n      \"additionalProperties\": {}\n    },\n    \"Links\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"Self\"\n      ],\n      \"properties\": {\n        \"Self\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"First\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"Prev\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"Next\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"Last\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        }\n      },\n      \"description\": \"Links relevant to the payload\",\n      \"additionalProperties\": {}\n    },\n    \"Meta\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"TotalPages\": {\n          \"type\": \"integer\",\n          \"format\": \"int32\"\n        },\n        \"FirstAvailableDateTime\": {\n          \"$ref\": \"#/definitions/ISODateTime\"\n        },\n        \"LastAvailableDateTime\": {\n          \"$ref\": \"#/definitions/ISODateTime\"\n        }\n      },\n      \"title\": \"MetaData\",\n      \"description\": \"Meta Data relevant to the payload\",\n      \"additionalProperties\": {}\n    },\n    \"ISODateTime\": {\n      \"type\": \"string\",\n      \"format\": \"date-time\",\n      \"description\": \"All dates in the JSON payloads are represented in ISO 8601 date-time format.\\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\"\n    },\n    \"OBError1\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"code\",\n        \"description\",\n        \"message\"\n      ],\n      \"properties\": {\n        \"code\": {\n          \"type\": \"string\",\n          \"description\": \"error code\"\n        },\n        \"message\": {\n          \"type\": \"string\",\n          \"description\": \"A description of the error that occurred. e.g., \\u0027A mandatory field isn\\u0027t supplied\\u0027 or \\u0027RequestedExecutionDateTime must be in future\\u0027\",\n          \"minLength\": 1,\n          \"maxLength\": 500\n        },\n        \"description\": {\n          \"type\": \"string\",\n          \"description\": \"A description of the error that occurred. e.g., \\u0027A mandatory field isn\\u0027t supplied\\u0027 or \\u0027RequestedExecutionDateTime must be in future\\u0027\",\n          \"minLength\": 1,\n          \"maxLength\": 1000\n        }\n      },\n      \"additionalProperties\": {}\n    },\n    \"OBErrorResponse1\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"errors\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/definitions/OBError1\"\n          },\n          \"minItems\": 1\n        }\n      }\n    }\n  },\n  \"parameters\": {\n    \"OBReadConsent1Param\": {\n      \"in\": \"body\",\n      \"name\": \"OBReadConsent1Param\",\n      \"description\": \"Default\",\n      \"required\": true,\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadConsent1\"\n      }\n    },\n    \"Authorization\": {\n      \"name\": \"Authorization\",\n      \"in\": \"header\",\n      \"description\": \"An Authorisation Token as per https://tools.ietf.org/html/rfc6750\",\n      \"required\": true,\n      \"type\": \"string\"\n    },\n    \"x-fapi-customer-ip-address\": {\n      \"name\": \"x-fapi-customer-ip-address\",\n      \"in\": \"header\",\n      \"description\": \"The PSU\\u0027s IP address if the PSU is currently logged in with the TPP.\",\n      \"required\": false,\n      \"type\": \"string\"\n    },\n    \"x-fapi-auth-date\": {\n      \"name\": \"x-fapi-auth-date\",\n      \"in\": \"header\",\n      \"description\": \"The time when the PSU last logged in with the TPP.\\nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below:\\nSun, 10 Sep 2017 19:43:31 UTC\",\n      \"required\": false,\n      \"type\": \"string\",\n      \"pattern\": \"^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\\\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\\\d{4} \\\\d{2}:\\\\d{2}:\\\\d{2} (GMT|UTC)$\"\n    },\n    \"ConsentId\": {\n      \"name\": \"ConsentId\",\n      \"in\": \"path\",\n      \"description\": \"ConsentId\",\n      \"required\": true,\n      \"type\": \"string\"\n    },\n    \"AccountId\": {\n      \"name\": \"AccountId\",\n      \"in\": \"path\",\n      \"description\": \"AccountId\",\n      \"required\": true,\n      \"type\": \"string\"\n    },\n    \"x-fapi-interaction-id\": {\n      \"name\": \"x-fapi-interaction-id\",\n      \"in\": \"header\",\n      \"description\": \"An RFC4122 UID used as a correlation id.\",\n      \"required\": false,\n      \"type\": \"string\"\n    }\n  },\n  \"responses\": {\n    \"201AccountAccessConsentsCreated\": {\n      \"description\": \"Account Access Consents Created\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadConsentResponse1\"\n      }\n    },\n    \"200AccountAccessConsentsConsentIdRead\": {\n      \"description\": \"Account Access Consents Read\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadConsentResponse1\"\n      }\n    },\n    \"204AccountAccessConsentsConsentIdDeleted\": {\n      \"description\": \"Account Access Consents Deleted\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"200AccountsRead\": {\n      \"description\": \"Accounts Read\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadAccount5\"\n      }\n    },\n    \"200AccountsAccountIdRead\": {\n      \"description\": \"Accounts Read\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadAccount4\"\n      }\n    },\n    \"200AccountsAccountIdBalancesRead\": {\n      \"description\": \"Balances Read\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadBalance1\"\n      }\n    },\n    \"200AccountsAccountIdTransactionsRead\": {\n      \"description\": \"Transactions Read\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBReadTransaction5\"\n      }\n    },\n    \"400Error\": {\n      \"description\": \"Bad request\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBErrorResponse1\"\n      }\n    },\n    \"401Error\": {\n      \"description\": \"Unauthorized\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"403Error\": {\n      \"description\": \"Forbidden\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBErrorResponse1\"\n      }\n    },\n    \"404Error\": {\n      \"description\": \"Not found\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"405Error\": {\n      \"description\": \"Method Not Allowed\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"406Error\": {\n      \"description\": \"Not Acceptable\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"415Error\": {\n      \"description\": \"Unsupported Media Type\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"429Error\": {\n      \"description\": \"Too Many Requests\",\n      \"headers\": {\n        \"Retry-After\": {\n          \"type\": \"integer\",\n          \"description\": \"Number in seconds to wait\"\n        },\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      }\n    },\n    \"500Error\": {\n      \"description\": \"Internal Server Error\",\n      \"headers\": {\n        \"x-fapi-interaction-id\": {\n          \"type\": \"string\",\n          \"description\": \"An RFC4122 UID used as a correlation id.\"\n        }\n      },\n      \"schema\": {\n        \"$ref\": \"#/definitions/OBErrorResponse1\"\n      }\n    }\n  }\n}',-1234),(348,_binary '<metadata xmlns=\"http://www.wso2.org/governance/metadata\"><overview><redirectURL></redirectURL><environments></environments><apiExternalProductionEndpoint></apiExternalProductionEndpoint><authorizationHeader>Authorization</authorizationHeader><type>HTTP</type><productionTps></productionTps><enableSchemaValidation>false</enableSchemaValidation><wsUriMapping>null</wsUriMapping><sandboxTimeUnit>1000</sandboxTimeUnit><context>/open-banking/v3.1/aisp</context><sandboxTps></sandboxTps><apiKeyHeader>ApiKey</apiKeyHeader><versionType>context</versionType><thumbnail></thumbnail><audience></audience><advertiseOnly>false</advertiseOnly><visibility>public</visibility><outSequence></outSequence><businessOwnerEmail></businessOwnerEmail><version>v3.1</version><enableSubscriberVerification>false</enableSubscriberVerification><visibleTenants></visibleTenants><cacheTimeout>300</cacheTimeout><enableStore>true</enableStore><asyncTransportProtocols></asyncTransportProtocols><gatewayVendor>wso2</gatewayVendor><websubSubscriptionConfiguration>null</websubSubscriptionConfiguration><name>AccountandTransactionAPI</name><endpointUsername></endpointUsername><responseCaching>Disabled</responseCaching><apiSecurit