ier>DefaultSubscriptionless</tier><provider>am_admin-AT-wso2.com</provider><endpointConfig>{\"endpoint_type\":\"default\",\"sandbox_endpoints\":{\"url\":\"default\"},\"failOver\":false,\"production_endpoints\":{\"url\":\"default\"}}</endpointConfig><vendor></vendor><inSequence></inSequence><audiences>[\"all\"]</audiences><testKey></testKey><endpointSecured>false</endpointSecured><endpointAuthDigest>false</endpointAuthDigest><tenants></tenants><endpointPpassword></endpointPpassword><versionComparable>1773859201462</versionComparable><wadl></wadl><technicalOwnerEmail></technicalOwnerEmail><implementation>ENDPOINT</implementation><apiOwner>am_admin@wso2.com</apiOwner><transports>http,https</transports><apiExternalSandboxEndpoint></apiExternalSandboxEndpoint><keyManagers>[\"all\"]</keyManagers><businessOwner></businessOwner></overview><monetizationProperties>{}</monetizationProperties><isMonetizationEnabled>false</isMonetizationEnabled></metadata>',-1234),(634,_binary '{\n  \"openapi\" : \"3.0.0\",\n  \"info\" : {\n    \"title\" : \"PaymentInitiationAPI\",\n    \"description\" : \"Swagger for Payment Initiation API Specification\",\n    \"version\" : \"v3.1\"\n  },\n  \"servers\" : [ {\n    \"url\" : \"/open-banking/{version}/pisp\"\n  } ],\n  \"paths\" : {\n    \"/payment-consents\" : {\n      \"post\" : {\n        \"tags\" : [ \"Payments\" ],\n        \"summary\" : \"Create Payment Consents\",\n        \"operationId\" : \"CreatePaymentConsents\",\n        \"parameters\" : [ {\n          \"$ref\" : \"#/components/parameters/x-fapi-auth-date\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-customer-ip-address\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-interaction-id\"\n        }, {\n          \"$ref\" : \"#/components/parameters/authorization\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-idempotency-key\"\n        } ],\n        \"requestBody\" : {\n          \"description\" : \"Default\",\n          \"content\" : {\n            \"application/json; charset=utf-8\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWriteConsent4\"\n              }\n            },\n            \"application/json\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWriteConsent4\"\n              }\n            },\n            \"application/jose+jwe\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWriteConsent4\"\n              }\n            }\n          },\n          \"required\" : true\n        },\n        \"responses\" : {\n          \"201\" : {\n            \"$ref\" : \"#/components/responses/201PaymentConsentsCreated\"\n          },\n          \"400\" : {\n            \"$ref\" : \"#/components/responses/400Error\"\n          },\n          \"401\" : {\n            \"$ref\" : \"#/components/responses/401Error\"\n          },\n          \"403\" : {\n            \"$ref\" : \"#/components/responses/403Error\"\n          },\n          \"405\" : {\n            \"$ref\" : \"#/components/responses/405Error\"\n          },\n          \"406\" : {\n            \"$ref\" : \"#/components/responses/406Error\"\n          },\n          \"415\" : {\n            \"$ref\" : \"#/components/responses/415Error\"\n          },\n          \"429\" : {\n            \"$ref\" : \"#/components/responses/429Error\"\n          },\n          \"500\" : {\n            \"$ref\" : \"#/components/responses/500Error\"\n          }\n        },\n        \"security\" : [ {\n          \"TPPOAuth2Security\" : [ \"payments\" ]\n        }, {\n          \"default\" : [ \"payments\" ]\n        } ],\n        \"x-auth-type\" : \"Application\",\n        \"x-throttling-tier\" : \"Unlimited\"\n      }\n    },\n    \"/payment-consents/{consentId}\" : {\n      \"get\" : {\n        \"tags\" : [ \"Payments\" ],\n        \"summary\" : \"Get Payment Consents\",\n        \"operationId\" : \"GetPaymentConsentsConsentId\",\n        \"parameters\" : [ {\n          \"$ref\" : \"#/components/parameters/consentId\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-auth-date\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-customer-ip-address\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-interaction-id\"\n        }, {\n          \"$ref\" : \"#/components/parameters/authorization\"\n        } ],\n        \"responses\" : {\n          \"200\" : {\n            \"$ref\" : \"#/components/responses/200PaymentConsentsConsentIdRead\"\n          },\n          \"400\" : {\n            \"$ref\" : \"#/components/responses/400Error\"\n          },\n          \"401\" : {\n            \"$ref\" : \"#/components/responses/401Error\"\n          },\n          \"403\" : {\n            \"$ref\" : \"#/components/responses/403Error\"\n          },\n          \"405\" : {\n            \"$ref\" : \"#/components/responses/405Error\"\n          },\n          \"406\" : {\n            \"$ref\" : \"#/components/responses/406Error\"\n          },\n          \"429\" : {\n            \"$ref\" : \"#/components/responses/429Error\"\n          },\n          \"500\" : {\n            \"$ref\" : \"#/components/responses/500Error\"\n          }\n        },\n        \"security\" : [ {\n          \"TPPOAuth2Security\" : [ \"payments\" ]\n        }, {\n          \"default\" : [ \"payments\" ]\n        } ],\n        \"x-auth-type\" : \"Application\",\n        \"x-throttling-tier\" : \"Unlimited\"\n      }\n    },\n    \"/payment-consents/{consentId}/funds-confirmation\" : {\n      \"get\" : {\n        \"tags\" : [ \"Payments\" ],\n        \"summary\" : \"Get Payment Consents Funds Confirmation\",\n        \"operationId\" : \"GetPaymentConsentsConsentIdFundsConfirmation\",\n        \"parameters\" : [ {\n          \"$ref\" : \"#/components/parameters/consentId\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-auth-date\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-customer-ip-address\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-interaction-id\"\n        }, {\n          \"$ref\" : \"#/components/parameters/authorization\"\n        } ],\n        \"responses\" : {\n          \"200\" : {\n            \"$ref\" : \"#/components/responses/200PaymentConsentsConsentIdFundsConfirmationRead\"\n          },\n          \"400\" : {\n            \"$ref\" : \"#/components/responses/400Error\"\n          },\n          \"401\" : {\n            \"$ref\" : \"#/components/responses/401Error\"\n          },\n          \"403\" : {\n            \"$ref\" : \"#/components/responses/403Error\"\n          },\n          \"405\" : {\n            \"$ref\" : \"#/components/responses/405Error\"\n          },\n          \"406\" : {\n            \"$ref\" : \"#/components/responses/406Error\"\n          },\n          \"429\" : {\n            \"$ref\" : \"#/components/responses/429Error\"\n          },\n          \"500\" : {\n            \"$ref\" : \"#/components/responses/500Error\"\n          }\n        },\n        \"security\" : [ {\n          \"PSUOAuth2Security\" : [ \"payments\" ]\n        }, {\n          \"default\" : [ \"payments\" ]\n        } ],\n        \"x-auth-type\" : \"Application & Application User\",\n        \"x-throttling-tier\" : \"Unlimited\"\n      }\n    },\n    \"/payments\" : {\n      \"post\" : {\n        \"tags\" : [ \"Payments\" ],\n        \"summary\" : \"Create Payments\",\n        \"operationId\" : \"CreatePayments\",\n        \"parameters\" : [ {\n          \"$ref\" : \"#/components/parameters/x-fapi-auth-date\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-customer-ip-address\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-interaction-id\"\n        }, {\n          \"$ref\" : \"#/components/parameters/authorization\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-idempotency-key\"\n        } ],\n        \"requestBody\" : {\n          \"description\" : \"Default\",\n          \"content\" : {\n            \"application/json; charset=utf-8\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWritePayment2\"\n              }\n            },\n            \"application/json\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWritePayment2\"\n              }\n            },\n            \"application/jose+jwe\" : {\n              \"schema\" : {\n                \"$ref\" : \"#/components/schemas/obWritePayment2\"\n              }\n            }\n          },\n          \"required\" : true\n        },\n        \"responses\" : {\n          \"201\" : {\n            \"$ref\" : \"#/components/responses/201PaymentsCreated\"\n          },\n          \"400\" : {\n            \"$ref\" : \"#/components/responses/400Error\"\n          },\n          \"401\" : {\n            \"$ref\" : \"#/components/responses/401Error\"\n          },\n          \"403\" : {\n            \"$ref\" : \"#/components/responses/403Error\"\n          },\n          \"405\" : {\n            \"$ref\" : \"#/components/responses/405Error\"\n          },\n          \"406\" : {\n            \"$ref\" : \"#/components/responses/406Error\"\n          },\n          \"415\" : {\n            \"$ref\" : \"#/components/responses/415Error\"\n          },\n          \"429\" : {\n            \"$ref\" : \"#/components/responses/429Error\"\n          },\n          \"500\" : {\n            \"$ref\" : \"#/components/responses/500Error\"\n          }\n        },\n        \"security\" : [ {\n          \"PSUOAuth2Security\" : [ \"payments\" ]\n        }, {\n          \"default\" : [ \"payments\" ]\n        } ],\n        \"x-auth-type\" : \"Application & Application User\",\n        \"x-throttling-tier\" : \"Unlimited\"\n      }\n    },\n    \"/payments/{paymentId}\" : {\n      \"get\" : {\n        \"tags\" : [ \"Payments\" ],\n        \"summary\" : \"Get Payments\",\n        \"operationId\" : \"GetPaymentsPaymentId\",\n        \"parameters\" : [ {\n          \"$ref\" : \"#/components/parameters/paymentId\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-auth-date\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-customer-ip-address\"\n        }, {\n          \"$ref\" : \"#/components/parameters/x-fapi-interaction-id\"\n        }, {\n          \"$ref\" : \"#/components/parameters/authorization\"\n        } ],\n        \"responses\" : {\n          \"200\" : {\n            \"$ref\" : \"#/components/responses/200PaymentsPaymentIdRead\"\n          },\n          \"400\" : {\n            \"$ref\" : \"#/components/responses/400Error\"\n          },\n          \"401\" : {\n            \"$ref\" : \"#/components/responses/401Error\"\n          },\n          \"403\" : {\n            \"$ref\" : \"#/components/responses/403Error\"\n          },\n          \"405\" : {\n            \"$ref\" : \"#/components/responses/405Error\"\n          },\n          \"406\" : {\n            \"$ref\" : \"#/components/responses/406Error\"\n          },\n          \"429\" : {\n            \"$ref\" : \"#/components/responses/429Error\"\n          },\n          \"500\" : {\n            \"$ref\" : \"#/components/responses/500Error\"\n          }\n        },\n        \"security\" : [ {\n          \"TPPOAuth2Security\" : [ \"payments\" ]\n        }, {\n          \"default\" : [ \"payments\" ]\n        } ],\n        \"x-auth-type\" : \"Application\",\n        \"x-throttling-tier\" : \"Unlimited\"\n      }\n    }\n  },\n  \"components\" : {\n    \"schemas\" : {\n      \"secondaryIdentification\" : {\n        \"maxLength\" : 34,\n        \"minLength\" : 1,\n        \"type\" : \"string\",\n        \"description\" : \"This is secondary identification of the account, as assigned by the account servicing institution. \\nThis can be used by building societies to additionally identify accounts with a roll number (in addition to a sort code and account number combination).\"\n      },\n      \"activeOrHistoricCurrencyCode\" : {\n        \"pattern\" : \"^[A-Z]{3,3}$\",\n        \"type\" : \"string\",\n        \"description\" : \"A code allocated to a currency by a Maintenance Agency under an international identification scheme, as described in the latest edition of the international standard ISO 4217 \\\"Codes for the representation of currencies and funds\\\".\"\n      },\n      \"isoDateTime\" : {\n        \"type\" : \"string\",\n        \"description\" : \"All dates in the JSON payloads are represented in ISO 8601 date-time format. \\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\",\n        \"format\" : \"date-time\"\n      },\n      \"meta\" : {\n        \"title\" : \"MetaData\",\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"TotalPages\" : {\n            \"type\" : \"integer\",\n            \"format\" : \"int32\"\n          },\n          \"FirstAvailableDateTime\" : {\n            \"$ref\" : \"#/components/schemas/isoDateTime\"\n          },\n          \"LastAvailableDateTime\" : {\n            \"$ref\" : \"#/components/schemas/isoDateTime\"\n          }\n        },\n        \"additionalProperties\" : false,\n        \"description\" : \"Meta Data relevant to the payload\"\n      },\n      \"obActiveCurrencyAndAmount_SimpleType\" : {\n        \"pattern\" : \"^\\\\d{1,13}$|^\\\\d{1,13}\\\\.\\\\d{1,5}$\",\n        \"type\" : \"string\",\n        \"description\" : \"A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.\"\n      },\n      \"obError1\" : {\n        \"minProperties\" : 1,\n        \"required\" : [ \"code\", \"description\", \"message\" ],\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"code\" : {\n            \"type\" : \"string\",\n            \"description\" : \"error code\"\n          },\n          \"message\" : {\n            \"maxLength\" : 500,\n            \"minLength\" : 1,\n            \"type\" : \"string\",\n            \"description\" : \"A description of the error that occurred. e.g., \'A mandatory field isn\'t supplied\' or \'RequestedExecutionDateTime must be in future\'\"\n          },\n          \"description\" : {\n            \"maxLength\" : 1000,\n            \"minLength\" : 1,\n            \"type\" : \"string\",\n            \"description\" : \"A description of the error that occurred. e.g., \'A mandatory field isn\'t supplied\' or \'RequestedExecutionDateTime must be in future\'\"\n          }\n        },\n        \"additionalProperties\" : false\n      },\n      \"obErrorResponse1\" : {\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"errors\" : {\n            \"minItems\" : 1,\n            \"type\" : \"array\",\n            \"items\" : {\n              \"$ref\" : \"#/components/schemas/obError1\"\n            }\n          }\n        }\n      },\n      \"obWriteFundsConfirmationResponse1\" : {\n        \"required\" : [ \"Data\" ],\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"Data\" : {\n            \"type\" : \"object\",\n            \"properties\" : {\n              \"FundsAvailableResult\" : {\n                \"required\" : [ \"FundsAvailable\", \"FundsAvailableDateTime\" ],\n                \"type\" : \"object\",\n                \"properties\" : {\n                  \"FundsAvailableDateTime\" : {\n                    \"type\" : \"string\",\n                    \"description\" : \"Date and time at which the funds availability check was generated.All dates in the JSON payloads are represented in ISO 8601 date-time format. \\nAll date-time fields in responses must include the timezone. An example is below:\\n2017-04-05T10:43:07+00:00\",\n                    \"format\" : \"date-time\"\n                  },\n                  \"FundsAvailable\" : {\n                    \"type\" : \"boolean\",\n                    \"description\" : \"Flag to indicate the availability of funds given the Amount in the consent request.\"\n                  }\n                },\n                \"additionalProperties\" : false,\n                \"description\" : \"Result of a funds availability check.\"\n              },\n              \"SupplementaryData\" : {\n                \"$ref\" : \"#/components/schemas/obSupplementaryData1\"\n              }\n            },\n            \"additionalProperties\" : false\n          },\n          \"Links\" : {\n            \"$ref\" : \"#/components/schemas/links\"\n          },\n          \"Meta\" : {\n            \"$ref\" : \"#/components/schemas/meta\"\n          }\n        },\n        \"additionalProperties\" : false\n      },\n      \"obExternalLocalInstrument1Code\" : {\n        \"type\" : \"string\",\n        \"description\" : \"User community specific instrument.\\nUsage: This element is used to specify a local instrument, local clearing option and/or further qualify the service or service level.\",\n        \"x-namespaced-enum\" : [ \"UK.OBIE.BACS\", \"UK.OBIE.BalanceTransfer\", \"UK.OBIE.CHAPS\", \"UK.OBIE.Euro1\", \"UK.OBIE.FPS\", \"UK.OBIE.Link\", \"UK.OBIE.MoneyTransfer\", \"UK.OBIE.Paym\", \"UK.OBIE.SEPACreditTransfer\", \"UK.OBIE.SEPAInstantCreditTransfer\", \"UK.OBIE.SWIFT\", \"UK.OBIE.Target2\" ]\n      },\n      \"obExternalAccountIdentification4Code\" : {\n        \"type\" : \"string\",\n        \"description\" : \"Name of the identification scheme, in a coded form as published in an external list.\",\n        \"x-namespaced-enum\" : [ \"OB.BBAN\", \"OB.IBAN\", \"OB.PAN\", \"OB.Paym\", \"OB.SortCodeAccountNumber\" ]\n      },\n      \"identification_0\" : {\n        \"maxLength\" : 256,\n        \"minLength\" : 1,\n        \"type\" : \"string\",\n        \"description\" : \"Identification assigned by an institution to identify an account. This identification is known by the account owner.\"\n      },\n      \"links\" : {\n        \"required\" : [ \"Self\" ],\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"Self\" : {\n            \"type\" : \"string\",\n            \"format\" : \"uri\"\n          }\n        },\n        \"additionalProperties\" : false,\n        \"description\" : \"Links relevant to the payload\"\n      },\n      \"obExternalPaymentChargeType1Code\" : {\n        \"type\" : \"string\",\n        \"description\" : \"Charge type, in a coded form.\",\n        \"x-namespaced-enum\" : [ \"UK.OBIE.CHAPSOut\" ]\n      },\n      \"obActiveOrHistoricCurrencyAndAmount\" : {\n        \"required\" : [ \"Amount\", \"Currency\" ],\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"Amount\" : {\n            \"$ref\" : \"#/components/schemas/obActiveCurrencyAndAmount_SimpleType\"\n          },\n          \"Currency\" : {\n            \"$ref\" : \"#/components/schemas/activeOrHistoricCurrencyCode\"\n          }\n        },\n        \"additionalProperties\" : false,\n        \"description\" : \"Amount of money associated with the charge type.\"\n      },\n      \"obSupplementaryData1\" : {\n        \"type\" : \"object\",\n        \"properties\" : { },\n        \"additionalProperties\" : true,\n        \"description\" : \"Additional information that can not be captured in the structured fields and/or any other specific block.\"\n      },\n      \"obChargeBearerType1Code\" : {\n        \"type\" : \"string\",\n        \"description\" : \"Specifies which party/parties will bear the charges associated with the processing of the payment transaction.\",\n        \"enum\" : [ \"BorneByCreditor\", \"BorneByDebtor\", \"FollowingServiceLevel\", \"Shared\" ]\n      },\n      \"obCashAccountDebtor4\" : {\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"SchemeName\" : {\n            \"type\" : \"string\",\n            \"description\" : \"^ Name of the identification scheme, in a coded form as published in an external list. | Namespaced Enumeration OBExternalAccountIdentification4Code\"\n          },\n          \"Identification\" : {\n            \"type\" : \"string\",\n            \"description\" : \"^ Identification assigned by an institution to identify an account. This identification is known by the account owner. | Max256Text\"\n          },\n          \"Name\" : {\n            \"type\" : \"string\",\n            \"description\" : \"^ Name of the account, as assigned by the account servicing institution.  Usage The account name is the name or names of the account owner(s) represented at an account level. The account name is not the product name or the nickname of the account.\"\n          },\n          \"SecondaryIdentification\" : {\n            \"type\" : \"string\",\n            \"description\" : \"^ This is secondary identification of the account, as assigned by the account servicing institution.  This can be used by building societies to additionally identify accounts with a roll number (in addition to a sort code and account number combination) | Max34Text\"\n          }\n        },\n        \"description\" : \"^ Only incuded in the response if `Data. ReadRefundAccount` is set to `Yes` in the consent.\"\n      },\n      \"obRisk1\" : {\n        \"type\" : \"object\",\n        \"properties\" : { },\n        \"additionalProperties\" : false,\n        \"description\" : \"The Risk section is sent by the initiating party to the ASPSP.\\nIt is used to specify additional details for risk scoring for Payments.    \"\n      },\n      \"obWriteConsent4\" : {\n        \"required\" : [ \"Data\", \"Risk\" ],\n        \"type\" : \"object\",\n        \"properties\" : {\n          \"Data\" : {\n            \"required\" : [ \"Initiation\" ],\n            \"type\" : \"object\",\n            \"properties\" : {\n              \"Initiation\" : {\n                \"required\" : [ \"CreditorAccount\", \"EndToEndIdentification\", \"InstructedAmount\", \"InstructionIdentification\" ],\n                \"type\" : \"object\",\n                \"properties\" : {\n                  \"InstructionIdentification\" : {\n                    \"maxLength\" : 35,\n                    \"minLength\" : 1,\n                    \"type\" : \"string\",\n                    \"description\" : \"Unique identification as assigned by an instructing party for an instructed party to unambiguously identify the instruction.\\nUsage: the  instruction identification is a point to point reference that can be used between the instructing party and the instructed party to refer to the individual instruction. It can be included in several messages related to the instruction.\"\n                  },\n                  \"EndToEndIdentification\" : {\n                    \"maxLength\" : 35,\n                    \"minLength\" : 1,\n                    \"type\" : \"string\",\n                    \"description\" : \"Unique identification assigned by the initiating party to unambiguously identify the transaction. This identification is passed on, unchanged, throughout the entire end-to-end chain.\\nUsage: The end-to-end identification can be used for reconciliation or to link tasks relating to the transaction. It can be included in several messages related to the transaction.\\nOB: The Faster Payments Scheme can only access 31 characters for the EndToEndIdentification field.\"\n                  },\n                  \"LocalInstrument\" : {\n                    \"$ref\" : \"#/components/schemas/obExternalLocalInstrument1Code\"\n                  },\n                  \"InstructedAmount\" : {\n                    \"required\" : [ \"Amount\", \"Currency\" ],\n                    \"type\" : \"object\",\n                    \"properties\" : {\n                      \"Amount\" : {\n                        \"$ref\" : \"#/components/schemas/obActiveCurrencyAndAmount_SimpleType\"\n                      },\n                      \"Currency\" : {\n                        \"$ref\" : \"#/components/schemas/activeOrHistoricCurrencyCode\"\n                      }\n                    },\n                    \"additionalProperties\" : false,\n                    \"description\" : \"Amount of money to be moved between the debtor and creditor, before deduction of charges, expressed in the currency as ordered by the initiating party.\\nUsage: This amount has to be transported unchanged through the transaction chain.\"\n                  },\n                  \"DebtorAccount\" : {\n                    \"required\" : [ \"Identification\", \"SchemeName\" ],\n                    \"type\" : \"object\",\n                    \"properties\" : {\n                      \"SchemeName\" : {\n                        \"$ref\" : \"#/components/schemas/obExternalAccountIdentification4Code\"\n                      },\n                      \"Identification\" : {\n                        \"$ref\" : \"#/components/schemas/identification_0\"\n                      },\n                      \"Name\" : {\n                        \"maxLength\" : 350,\n                        \"minLength\" : 1,\n                        \"type\" : \"string\",\n                        \"description\" : \"The account name is the name or names of the account owner(s) represented at an account level, as displayed by the ASPSP\'s online channels.\\nNote, the account name is not the product name or the nickname of the account.\"\n                      },\n                      \"SecondaryIdentification\" : {\n                        \"$ref\" : \"#/components/schemas/secondaryIdentification\"\n                      }\n                    },\n                    \"additionalProperties\" : false,\n                    \"description\" : \"Unambiguous identification of the account of the debtor to which a debit entry will be made as a result of the transaction.\"\n                  },\n                  \"CreditorAccount\" : {\n                    \"required\" : [ \"Identification\", \"Name\", \"SchemeName\" ],\n               