v {\r\n    background-image: url( ../images/api-header-back.png);\r\n    height:80px;\r\n}\r\n\r\ndiv#header-div div.left-logo {\r\n	background-image: url( ../images/api-logo.png );\r\n	   margin-left: 30px;\r\n    margin-top: 25px;\r\n	\r\n	width:246px;\r\n	height:50px;\r\n}\r\n\r\ndiv#header-div div.right-logo {\r\n	/*background-image:url(\"../images/right-logo-bg.gif\");\r\n	background-position:right top;\r\n	background-repeat:no-repeat;*/\r\n	color:#cc362b;\r\n	height:32px;\r\n	margin-right:20px;\r\n	line-height: 30px;\r\n	margin-top:7px;\r\n	padding-right:0px;\r\n	padding-top:5px;\r\n}\r\ndiv#header-div div.header-links {\r\n	margin-top:-20px;\r\n}\r\ndiv#header-div div.header-links div.right-links {\r\n	margin-right: 0px;\r\n	height: 35px;\r\n	padding-top: 0px;\r\n}\r\ndiv#header-div div.header-links div.right-links ul {\r\n	background:none;\r\n	padding-left: 25px;\r\n	padding-right: 15px;\r\n	padding-top: 0px;\r\n	padding-bottom: 7px;\r\n}\r\n#logged-user{\r\n    color:#555;\r\n}\r\n/* ------------- menu styles ---------------------- */\r\ndiv#menu {\r\n}\r\n\r\ndiv#menu ul.main {\r\n}\r\n\r\ndiv#menu ul.main li {\r\n}\r\n\r\ndiv#menu ul.main li.normal {\r\n}\r\n\r\ndiv#menu ul.main li a.menu-home {\r\nbackground-image:url(../images/menu_header.gif);\r\nheight:28px;\r\n}\r\n\r\ndiv#menu ul.main li.menu-header {\r\n	background-image: url(../images/api-server-menu-header.gif);\r\n	background-position: left bottom;\r\n	background-repeat: repeat-x;\r\n	height: 32px;\r\n	line-height: 32px;\r\n}\r\n\r\ndiv#menu ul.main li a.menu-default {\r\n}\r\n\r\ndiv#menu ul.main li a.menu-default:hover {\r\n	background-color: #EFECF5;\r\n	border-bottom: solid 1px #C2B7D8;\r\n	border-top: solid 1px #C2B7D8;\r\n	color: #00447C;\r\n}\r\n\r\ndiv#menu ul.sub {\r\n}\r\n\r\n/* -------------- child no-01 styles -------------- */\r\n\r\ndiv#menu ul.sub li.normal {\r\n\r\n}\r\n\r\ndiv#menu ul.sub li a.menu-default {\r\n}\r\n\r\n/* ----------- child no-01 (disabled) styles --------------