 ../images/facts-selector.gif );\r\n    background-repeat: no-repeat;\r\n    background-position: left top;\r\n    padding-left: 20px;\r\n    line-height: 17px;\r\n    height: 17px;\r\n    float: left;\r\n    position: relative;\r\n    margin-left: 10px;\r\n    margin-top: 5px;\r\n    margin-bottom: 3px;\r\n    white-space: nowrap;\r\n}\r\ntable#main-table td#middle-content {\r\nbackground-color:#f5f6fb;\r\n}\r\ndiv#middle{\r\nbackground-color:#f5f6fb;\r\n}\r\ndiv#middle h2{\r\ncolor:#8a2c3f;\r\n}\r\ndiv#menu ul.main li.menu-disabled-link{\r\n	background-color:#eff1f9;\r\n}\r\n',-1234),(653,_binary '<metadata xmlns=\"http://www.wso2.org/governance/metadata\"><overview><redirectURL></redirectURL><environments></environments><apiExternalProductionEndpoint></apiExternalProductionEndpoint><authorizationHeader>Authorization</authorizationHeader><type>HTTP</type><productionTps></productionTps><enableSchemaValidation>false</enableSchemaValidation><wsUriMapping>null</wsUriMapping><sandboxTimeUnit>1000</sandboxTimeUnit><context>/open-banking/v3.1/aisp</context><sandboxTps></sandboxTps><apiKeyHeader>ApiKey</apiKeyHeader><versionType>context</versionType><thumbnail></thumbnail><audience></audience><advertiseOnly>false</advertiseOnly><visibility>public</visibility><outSequence></outSequence><businessOwnerEmail></businessOwnerEmail><version>v3.1</version><enableSubscriberVerification>false</enableSubscriberVerification><visibleTenants></visibleTenants><cacheTimeout>300</cacheTimeout><enableStore>true</enableStore><asyncTransportProtocols></asyncTransportProtocols><gatewayVendor>wso2</gatewayVendor><websubSubscriptionConfiguration>null</websubSubscriptionConfiguration><name>AccountandTransactionAPI</name><endpointUsername></endpointUsername><responseCaching>Disabled</responseCaching><apiSecurity>oauth_basic_auth_api_key_mandatory,oauth2</apiSecurity><status>PUBLISHED</status><organizationTiers></organizationTiers><productionTimeUnit>1000</productionTimeUnit><contextTemplate>/open