INSERT INTO `reg_content` VALUES (654,_binary '{\n  \"swagger\": \"2.0\",\n  \"info\": {\n    \"description\": \"Swagger for Account and Transaction API Specification\",\n    \"version\": \"v3.1\",\n    \"title\": \"AccountandTransactionAPI\"\n  },\n  \"basePath\": \"/open-banking/{version}/aisp\",\n  \"tags\": [\n    {\n      \"name\": \"Account Access\",\n      \"description\": \"Account Access Consents\"\n    },\n    {\n      \"name\": \"Accounts\",\n      \"description\": \"Accounts\"\n    },\n    {\n      \"name\": \"Balances\",\n      \"description\": \"Balances\"\n    },\n    {\n      \"name\": \"Transactions\",\n      \"description\": \"Transactions\"\n    }\n  ],\n  \"schemes\": [\n    \"https\"\n  ],\n  \"consumes\": [\n    \"application/json; charset\\u003dutf-8\"\n  ],\n  \"produces\": [\n    \"application/json; charset\\u003dutf-8\"\n  ],\n  \"security\": [\n    {\n      \"default\": []\n    }\n  ],\n  \"paths\": {\n    \"/account-access-consents\": {\n      \"post\": {\n        \"tags\": [\n          \"Account Access\"\n        ],\n        \"summary\": \"Create Account Access Consents\",\n        \"operationId\": \"CreateAccountAccessConsents\",\n        \"parameters\": [\n          {\n            \"in\": \"body\",\n            \"name\": \"OBReadConsent1Param\",\n            \"description\": \"Default\",\n            \"required\": true,\n            \"schema\": {\n              \"$ref\": \"#/definitions/OBReadConsent1\"\n            }\n          },\n          {\n            \"name\": \"x-fapi-auth-date\",\n            \"in\": \"header\",\n            \"description\": \"The time when the PSU last logged in with the TPP.\\nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below:\\nSun, 10 Sep 2017 19:43:31 UTC\",\n            \"required\": false,\n            \"type\": \"string\",\n            \"pattern\": \"^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\\\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\\\d{4} \\\\d{2}:\\\\d