nary '<log level=\"custom\">\n    <property name=\"MESSAGE\" value=\"json_validator\"/>\n</log>\n<property name=\"maxPropertyCount\"  value = \"{{maxPropertyCount}}\"/>\n<property name=\"maxStringLength\"  value = \"{{maxStringLength}}\"/>\n<property name=\"maxArrayElementCount\"  value = \"{{maxArrayElementCount}}\"/>\n<property name=\"maxKeyLength\"  value = \"{{maxKeyLength}}\"/>\n<property name=\"maxJsonDepth\"  value = \"{{maxJsonDepth}}\"/>\n<property name=\"RequestMessageBufferSize\" value=\"{{requestMessageBufferSize}}\"/>\n<class name=\"{{jsonSchemaValidator}}\"/>','Synapse','{\"hash\":\"ceafad67dfb3f873d174239a6bb0917d3b0cb355fcd0f809d32d9b73c4afa80a\",\"algorithm\":\"SHA-256\"}'),(16,'dca01f46-d2cf-4ee5-a5da-6669eaea95b6',_binary '<class name=\"org.wso2.carbon.apimgt.gateway.mediators.WeightedRoundRobinMediator\">\n	<property action=\"set\" name=\"weightedRoundRobinConfigs\" value=\"{{weightedRoundRobinConfigs}}\" scope=\"transport\" />\n</class>\n','Synapse','{\"hash\":\"0a3aa197aaa7f90e41476cdd42ec5f4edb2bba7541f525267688c18c1c1ff009\",\"algorithm\":\"SHA-256\"}'),(17,'1181787c-49b3-4424-8fa4-092d11539a36',_binary '<log level=\"full\">\n	<property name=\"OUT_MESSAGE\" value=\"OUT_MESSAGE\"/>\n</log>\n<log level=\"custom\">\n	<property name=\"Endpoint\" expression=\"get-property(\'ENDPOINT_PREFIX\')\"/>\n    <property name=\"Content-Type\" expression=\"get-property(\'transport\', \'Content-Type\')\"/>\n    <property name=\"Correlation_Id\" expression=\"get-property(\'msgID\')\" scope=\"axis2\" />\n</log>','Synapse','{\"hash\":\"2dfb8a13ca92a3a2587ac15e7a35f5cb6f0e9c7bedf460cd88ce781fb1c65c1b\",\"algorithm\":\"SHA-256\"}'),(18,'d403e4d0-9078-4ce4-a4cc-ddc7f5b6d8be',_binary '<property name=\"messageType\" expression=\"get-property(\'default\', \'WSO2_AM_API_ACCEPT_MESSAGE_TYPE\')\" scope=\"axis2\"/>','Synapse','{\"hash\":\"f75abe1d86b132a8698bef9c2d1fa28b73065344cfacbf52d8e0a7ce1e109422\",\"algorithm\":\"SHA-256\"}'),(19,'38747b19-ffa6-40df-b8e5-8941993e76