  `DESCRIPTION` varchar(1024) DEFAULT NULL,
  `ARTIFACT_TYPE` varchar(128) NOT NULL,
  `RULE_CATEGORY` varchar(128) NOT NULL,
  `RULE_TYPE` varchar(128) NOT NULL,
  `DOCUMENTATION_LINK` varchar(1024) DEFAULT NULL,
  `PROVIDER` varchar(256) DEFAULT NULL,
  `ORGANIZATION` varchar(128) NOT NULL,
  `CREATED_BY` varchar(256) DEFAULT NULL,
  `CREATED_TIME` datetime DEFAULT CURRENT_TIMESTAMP,
  `UPDATED_BY` varchar(256) DEFAULT NULL,
  `LAST_UPDATED_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`RULESET_ID`),
  UNIQUE KEY `RULESET_CONSTRAINT` (`NAME`,`ORGANIZATION`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
