INSERT INTO `gov_ruleset` VALUES ('2ac0ef0f-acd3-4953-9843-711f8d04624f','WSO2 REST API Design Guidelines','A set of guidelines focused on enforcing uniformity in API style, including naming conventions, formatting, and documentation to ensure clarity and maintainability across all APIs.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-rest-api-design-guidelines/','WSO2','carbon.super',NULL,'2026-03-09 14:05:58',NULL,NULL),('87ca8ddb-8b78-4330-b487-44d01489664d','OWASP Top 10','A set of rules enforcing OWASP security guidelines to prevent common vulnerabilities and ensure secure coding practices.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/owasp-top-10/','WSO2','carbon.super',NULL,'2026-03-09 14:05:58',NULL,NULL),('94c5e1bd-e83c-4559-81e5-ea68e864421a','WSO2 API Management Guidelines','A guide detailing best practices for creating robust, scalable, and secure APIs, ensuring alignment with industry standards for optimal design.','REST_API','SPECTRAL','API_METADATA','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-api-management-guidelines/','WSO2','carbon.super',NULL,'2026-03-09 14:05:58',NULL,NULL);
